var t=`0836-dal-tadka`;var n=`world-0836`;var a=`IN`;var s=`south-asia`;var r=4;var d=40;var l={en:`Dal Tadka`,ua:`Дал тадка`};var o={en:`Dal Tadka is a India dish made with red lentils, garlic, dried arbol chilies, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Дал тадка, страва кухні країни Індія. Основні складники: червона сочевиця, часник, сушений перець арболь, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`red-lentils`,330,`g`],[`water`,1050,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`ghee`,60,`g`],[`cumin-seeds`,7,`g`],[`garlic`,5,`clove`],[`dried-arbol-chilies`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`tomato`,180,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`]]}];var m={slug:t,id:n,country:`IN`,region:s,servings:4,minutes:40,title:l,text:o,steps:g};export{a as country,m as default,n as id,d as minutes,s as region,r as servings,t as slug,g as steps,o as text,l as title};